<?php
declare(strict_types=1);
return static function(PDO $db):void{
    $root=dirname(__DIR__);$now=gmdate('c');
    foreach(['hero-medusa.webp','joao-portrait.webp','nina-preview.mp4','nina-poster.webp'] as $name){$file=$root.'/assets/media/'.$name;if(!is_file($file))continue;$checksum=hash_file('sha256',$file);$q=$db->prepare('SELECT id FROM media_assets WHERE checksum=? LIMIT 1');$q->execute([$checksum]);if($q->fetchColumn())continue;$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file);$kind=str_starts_with($mime,'video/')?'video':'image';$size=filesize($file);$width=null;$height=null;if($kind==='image'){[$width,$height]=getimagesize($file)?:[null,null];}$uuid=bin2hex(random_bytes(16));$version=bin2hex(random_bytes(16));$db->prepare('INSERT INTO media_assets(asset_uuid,kind,title,original_name,mime_type,byte_size,width,height,checksum,processing_status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,"ready",?,?)')->execute([$uuid,$kind,pathinfo($name,PATHINFO_FILENAME),$name,$mime,$size,$width,$height,$checksum,$now,$now]);$asset=(int)$db->lastInsertId();$db->prepare('INSERT INTO media_versions(asset_id,version_uuid,original_path,mime_type,byte_size,width,height,checksum,processing_status,created_at) VALUES(?,?,?,?,?,?,?, ?,"ready",?)')->execute([$asset,$version,'../../assets/media/'.$name,$mime,$size,$width,$height,$checksum,$now]);$versionId=(int)$db->lastInsertId();$db->prepare('UPDATE media_assets SET active_version_id=? WHERE id=?')->execute([$versionId,$asset]);}
};
